export function SocialProof({
  statNumber = "{{statNumber}}",
  statLabel = "{{statLabel}}",
  rating = {{rating}},
  showAvatars = {{showAvatars}},
  accent = "{{accent}}",
  layout = "{{layout}}",
}) {
  const stacked = layout === "stacked";
  return (
    <div style={{
      display: "flex", flexDirection: stacked ? "column" : "row", alignItems: stacked ? "flex-start" : "center",
      gap: stacked ? 8 : 14, flexWrap: "wrap", fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430",
    }}>
      {showAvatars && (
        <div style={{ display: "flex" }} role="presentation">
          {["JM", "AK", "RT"].map((initials, i) => (
            <span key={initials} style={{
              display: "inline-flex", alignItems: "center", justifyContent: "center", width: 32, height: 32,
              borderRadius: 999, background: "#241430", color: "#FAF7F2", fontSize: 11, fontWeight: 600,
              border: "2px solid #FAF7F2", marginLeft: i === 0 ? 0 : -8,
            }}>{initials}</span>
          ))}
          <span style={{
            display: "inline-flex", alignItems: "center", justifyContent: "center", width: 32, height: 32,
            borderRadius: 999, background: accent, color: "#241430", fontSize: 11, fontWeight: 600,
            border: "2px solid #FAF7F2", marginLeft: -8,
          }}>+9k</span>
        </div>
      )}
      <p style={{ margin: 0 }}><strong>{statNumber}</strong> {statLabel}</p>
      <div style={{ display: "inline-flex", alignItems: "center", gap: 6 }} role="img" aria-label={`Rated ${rating} out of 5`}>
        <span style={{ position: "relative", display: "inline-block", fontSize: 15, lineHeight: 1, letterSpacing: 1 }} aria-hidden="true">
          <span style={{ color: "#24143026" }}>★★★★★</span>
          <span style={{ position: "absolute", inset: 0, width: `calc(${rating} / 5 * 100%)`, overflow: "hidden",
            whiteSpace: "nowrap", color: accent }}>★★★★★</span>
        </span>
        <span style={{ fontSize: 13, color: "#241430aa" }}>{rating}</span>
      </div>
    </div>
  );
}
